challenge.solution:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;if(scanf("%d",&n)!=1||n<1||n>20)return 1;
    int*p=malloc((size_t)n*sizeof*p);if(!p)return 1;
    for(int i=0;i<n;i++)if(scanf("%d",&p[i])!=1){free(p);return 1;}
    int x;if(scanf("%d",&x)!=1){free(p);return 1;}
    int*next=realloc(p,(size_t)(n+1)*sizeof*p);if(!next){free(p);return 1;}p=next;for(int i=n;i>0;i--)p[i]=p[i-1];p[0]=x;
    for(int i=0;i<=n;i++)printf("%s%d",i?" ":"",p[i]);putchar('\n');free(p);
    return 0;
}
